def remove_elements(lst, elements):
    """Remove all elements from `elements` in `lst` in-place and return the new length.

    Args:
        lst: A list of elements.
        elements: A list of elements to remove from `lst`.

    Returns:
        The new length of `lst` after removing all elements.
    """
    if not lst:
        return 0
    for i in range(len(lst)):
        if lst[i] == elements[i]:
            lst.pop(i)
    return len(lst)

def odd_values_string(s):
    """Remove the characters which have odd index values of a string.

    Args:
        s: A string.

    Returns:
        The string with the characters removed.
    """
    odd_chars = []
    for char in s:
        if char in odd_chars:
            odd_chars.remove(char)
    return ''.join(odd_chars)

