def even_binomial_Coeff_Sum(n):
    """
    Compute the sum of even binomial coefficients for n.

    Args:
        n (int): A positive integer.

    Returns:
        int: The sum of even binomial coefficients.

    Raises:
        ValueError: If n is not a positive integer.
    """
    if not isinstance(n, int) or n <= 0:
        raise ValueError("n must be a positive integer")
    if n == 1:
        return 1
    if n == 2:
        return 2
    if n % 2 == 0:
        return 2 + even_binomial_Coeff_Sum(n // 2)
    else:
        return 2 + even_binomial_Coeff_Sum(n - 1)

def is_num_decagonal(n: int) -> bool:
    """Check if a number is a decagonal number.

    A decagonal number is a number that is equal to the sum of its
    positive divisors (excluding 1 and itself).

    Args:
        n: A positive integer.

    Returns:
        True if n is a decagonal number, False otherwise.
    """
    if n <= 1:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    for i in range(3, int(n**0.5) + 1, 2):
        if n % i == 0:
            return False
    return True

