def max_length(list):
    """Return the maximum length of a list of lists.

    Args:
        list: A list of lists.

    Returns:
        The maximum length of the list.
    """
    if not list:
        return 0
    max_length = 0
    for i in range(len(list)):
        for j in range(i + 1, len(list)):
            if list[i][0] > list[j][0]:
                max_length = max(max_length, len(list[i]) + len(list[j]))
    return max_length

