def shell_sort(arr):
    """Sort the given array using shell sort.

    Args:
        arr: A list of integers.

    Returns:
        The same list sorted in ascending order.
    """
    n = len(arr)
    for i in range(n):
        for j in range(i + 1, n):
            if arr[j] > arr[j - 1]:
                arr[j], arr[j - 1] = arr[j - 1], arr[j]
    return arr

def remove_odd(s):
    """Remove all odd characters from the input string.

    Args:
        s: A string to process.

    Returns:
        The string with all odd characters removed.
    """
    odd_chars = []
    for char in s:
        if char in odd_chars:
            odd_chars.remove(char)
    return "".join(odd_chars)

