def triangle_area(radius):
    """Return the area of the largest triangle that can be inscribed in a semicircle with a given radius.

    Args:
        radius: A positive number representing the radius of the semicircle.

    Returns:
        The area of the largest triangle that can be inscribed in the semicircle.
        Returns 0 if no such triangle exists.
    """
    if radius <= 0:
        return 0
    triangle = 0
    for i in range(1, radius + 1):
        for j in range(i):
            if i == j:
                continue
            if i * j > radius:
                triangle += 1
    return triangle

