    """Check if a number is a nonagonal number.

    A nonagonal number is a number that is equal to the sum of the squares
    of its digits each raised to the power of the number of digits.

    Args:
        n: An integer.

    Returns:
        True if n is a nonagonal number, False otherwise.
    """
    if n == 0:
        return False
    if n == 1:
        return True
    if n % 2 == 0:
        return False
    return is_nonagonal(n // 2) and is_nonagonal(n // 3)

