    """Rotate a list by a number of items to the right.

    Args:
        nums: A list of integers.

    Returns:
        The same list after rotation by `nums` items.
    """
    n = len(nums)
    if n == 0:
        return nums
    if n == 1:
        return nums[0]
    if n == 2:
        return nums[0] + nums[1]
    if n == 3:
        return nums[0] + nums[1] + nums[2]
    if n == 4:
        return nums[0] + nums[1] + nums[2] + nums[3]
    if n == 5:
        return nums[0] + nums[1] + nums[2] + nums[3] + nums[4]
    if n == 6:
