def check_expression(expression: str) -> bool:
    """Check if the given expression is balanced or not.

    Args:
        expression: A string representing a valid expression.

    Returns:
        True if the expression is balanced, False otherwise.
    """
    stack = []
    for char in expression:
        if char == '(':
            stack.append(char)
        elif char == ')':
            if not stack:
                return False
            stack.pop()
        else:
            if not stack:
                return False
            stack.append(char)
    return len(stack) == 0

def occurance_substring(s: str) -> tuple:
    """Return the occurrence and position of the substrings in the string s.

    Args:
        s: A string to search for.

    Returns:
        A tuple (occurrence, position) where occurrence is the position
        of the first occurrence of the substring in s, and position is
        the position of the first occurrence of the substring in s.
    """
    occurrence = 0
    position = 0
    for i in range(len(s)):
        if s[i] == s[occurrence]:
            occurrence += 1
        elif s[i] == s[position]:
            position += 1
        else:
            return (occurrence, position)
    return (occurrence, position)

def text_match_three(text):
    """
    Check if the given string has an a followed by three 'b'.
    """
    if not text:
        return False
    if len(text) == 3:
        return True
    if text[0] == 'b' and text[1] == 'b':
        return True
    return False

def text_starta_endb(text):
    """Return True if the string starts with 'a' followed by 'b'."""
    return text.startswith('a') and text.endswith('b')

def assert_text_starta_endb(text):
    """Check if the string starts with 'a' followed by 'b'."""
    assert text_starta_endb(text) == 'a'
    assert text_starta_endb(text) == 'b'

def sum_in_range(l, r):
